from pathlib import Path
import json,zipfile
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'build/diagnostics/boss_dynamic'
def main():
 renderer=(ROOT/'scripts/boss_dynamic_renderer.mjs').read_text().replace('export ','');sprites=(OUT/'sprites.json').read_text()
 html='''<!doctype html><meta charset="utf-8"><title>Independent boss parts</title><style>body{background:#16191e;color:#e7ecf5;font:17px system-ui;max-width:1000px;margin:25px auto;padding:0 15px}canvas{image-rendering:pixelated;max-width:100%;background:black;touch-action:none}button,label{font:inherit;margin:6px;padding:6px}a{color:#7ddcff}#stats{font:15px monospace;white-space:pre-line}</style><h1>Independent boss parts</h1><p>Drag a sphere or machinery core. Arrow keys move the selected part by one pixel. Keys1–6 select parts. No pre-recorded formation or complete boss frames.</p><div><button id="reset">Reset</button><button id="random">Rearrange</button><button id="cel">Next cel</button><button id="flip">Flip selected</button><button id="front">Bring selected forward</button><label><input id="animate" type="checkbox">Independent animation</label><label><input id="stars" type="checkbox">Star backdrop</label></div><canvas width="256" height="192" style="width:768px;height:576px"></canvas><p id="stats"></p><p>Sprite phase samples → old/new damage cells → compose intersecting parts in depth order → choose legal8×1 colours → paired-plane XOR publication. Only damaged cells are recomposed.</p><p><b>Evidence limits:</b> composition and stream generation run in JavaScript here. The same delta publisher was tested as native Z80 against100 arbitrary changing arrangements, including overlap, clipping, flips, depth changes, removal and backdrop changes. This is not a complete native game speed measurement or integration.</p><p><a href="validation.json">Native validation</a></p><script>'''+renderer+'\nconst sprites='+sprites+';'+r'''
const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),scene=new BossScene(sprites),stats=document.querySelector('#stats');let parts=[],selected=1,drag=null,now=0,last=0;
function reset(){parts=[{id:0,cel:3,x:123,y:47},...Array.from({length:5},(_,i)=>({id:i+1,cel:i%3,x:72+(i%3)*32,y:27+Math.floor(i/3)*68}))];selected=1;draw(true);}
function draw(full=false){const changes=scene.update(parts,{background:document.querySelector('#stars').checked,full});const im=ctx.createImageData(256,192);for(let y=0;y<192;y++)for(let x=0;x<256;x++){const at=offset(y)+(x>>3),a=scene.attrs[at],bit=scene.pix[at]&(128>>(x&7)),c=(bit?a&7:(a>>3)&7)+(a&64?8:0),p=(y*256+x)*4;im.data.set([...palette[c],255],p);}ctx.putImageData(im,0,0);stats.textContent=`Selected part ${selected+1} | dirty ${scene.composedCells}/6144 cells | changed ${changes.length} | XOR stream ${encodeChanges(changes).length} bytes | cached row samples ${scene.cache.size}\nClash cost ${Math.round(scene.colourErrors)}: every cell uses a legal ECM pair; masks cannot preserve more than two colours.`;}
canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*256/r.width),y=Math.floor((e.clientY-r.top)*192/r.height);for(let i=parts.length-1;i>=0;i--){const p=parts[i],s=sprites[p.cel];if(x>=p.x&&x<p.x+s.width&&y>=p.y&&y<p.y+s.height){selected=p.id;drag={dx:x-p.x,dy:y-p.y};canvas.setPointerCapture(e.pointerId);break;}}};
canvas.onpointermove=e=>{if(!drag)return;const r=canvas.getBoundingClientRect(),p=parts.find(p=>p.id===selected);p.x=Math.max(-24,Math.min(240,Math.round((e.clientX-r.left)*256/r.width-drag.dx)));p.y=Math.max(-24,Math.min(180,Math.round((e.clientY-r.top)*192/r.height-drag.dy)));draw();};canvas.onpointerup=()=>drag=null;
document.onkeydown=e=>{if(/^[1-6]$/.test(e.key)){selected=Number(e.key)-1;return;}const p=parts.find(p=>p.id===selected),d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(d){e.preventDefault();p.x+=d[0];p.y+=d[1];draw();}};
document.querySelector('#reset').onclick=reset;document.querySelector('#random').onclick=()=>{for(const p of parts){p.x=Math.floor(Math.random()*230)-15;p.y=Math.floor(Math.random()*180)-15;}draw();};document.querySelector('#cel').onclick=()=>{const p=parts.find(p=>p.id===selected);if(p.cel<3)p.cel=(p.cel+1)%3;draw();};document.querySelector('#flip').onclick=()=>{const p=parts.find(p=>p.id===selected);p.flipX=!p.flipX;draw();};document.querySelector('#front').onclick=()=>{const p=parts.find(p=>p.id===selected);parts=parts.filter(q=>q!==p).concat(p);draw();};document.querySelector('#stars').onchange=()=>draw();
function animate(t){if(document.querySelector('#animate').checked&&!drag&&t-last>90){last=t;now++;for(const p of parts)if(p.cel<3){p.x=Math.max(-24,Math.min(245,p.x+Math.round(Math.sin((now+p.id*4)/9)*2)));p.y=Math.max(-24,Math.min(185,p.y+Math.round(Math.cos((now+p.id*7)/11)*2)));p.cel=(p.cel+1)%3;}draw();}requestAnimationFrame(animate);}reset();requestAnimationFrame(animate);
</script>'''
 (OUT/'index.html').write_text(html,encoding='utf-8')
 with zipfile.ZipFile(OUT/'Independent_boss_delta_prototype.zip','w',zipfile.ZIP_DEFLATED)as z:
  for name in ['index.html','sprites.json','validation.json']:z.write(OUT/name,name)
 print(OUT/'index.html')
if __name__=='__main__':main()
